-- проверка округления отношения до 6 знаков через целые частное и остаток для неотрицательной добычи.
WITH a AS (SELECT oil_tonnes,producing_well_days,oil_per_well_day,CAST(oil_tonnes*DECIMAL '1000000' AS decimal(25,0)) AS numerator FROM {{target:oil_mart__agg_field_day}}), r AS (SELECT *,mod(numerator,CAST(nullif(producing_well_days,0) AS decimal(19,0))) AS remainder FROM a), e AS (SELECT *,CAST((CAST((numerator-remainder)/CAST(nullif(producing_well_days,0) AS decimal(19,0)) AS decimal(25,0))+CASE WHEN remainder*DECIMAL '2'>=producing_well_days THEN DECIMAL '1' ELSE DECIMAL '0' END)*DECIMAL '0.000001' AS decimal(22,6)) AS expected FROM r) SELECT count(*) AS n FROM e WHERE oil_tonnes<0 OR producing_well_days<0 OR oil_per_well_day IS DISTINCT FROM expected;
